  0 <= maxval <= 255 -> 0x10007fff8000 <= S1 -> S1 + 224 <= 2^47 -> (S1 + 224 <= kfr \/ kfr + 1024 <= S1) ->
  fs_agree F0 F -> frm0 fc ->
