Definition kfin_post (kfr n S1 : Z) (ra sp gp tp s0 s1 a3 a4 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 : bvmap 5 word) (m0 : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem) (kfs' : list Z),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 kfr) a1' a2' a3 a4 (Z_to_bv 64 1) (Z_to_bv 64 n) (Z_to_bv 64 1)
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F' (Z_to_bv 64 0xd0014) fc' None m' (seg_rom asegs)
    /\ fs_agree F0 F' /\ frm0 fc' /\ munch [(kfr, kfr + 1024)] m0 m' /\ wmono asegs m0 m' /\ mem_inv asegs m'
    /\ u32arr asegs m' kfr (map (Z_to_bv 64) kfs') /\ length kfs' = 256%nat /\ Forall FpSiteB.kfr_le1 kfs'
    /\ wr_at asegs m' kfr 1024 /\ acc asegs m' kfr 1024.
Lemma kfr_inner : forall (j : nat) (i a b : Z)
    (ra sp gp tp t1 t2 s0 s1 a3 a4 s2 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 F : bvmap 5 word) (fc : bv 32) (m0 m : mem) (kfr S1 : Z) (kfs : list Z),
  Z.of_nat j = b - i -> 0 <= a <= i -> i < b <= 255 ->
  0 < kfr -> kfr mod 16 = 0 -> kfr + 1024 <= 2^47 -> (kfr + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= kfr) ->
  0x10007fff8000 <= S1 -> S1 + 224 <= 2^47 -> (S1 + 224 <= kfr \/ kfr + 1024 <= S1) ->
  fs_agree F0 F -> reg_get F (15%bv : bv 5) = fcvt_s_w RNE (Z_to_bv 64 b) -> reg_get F (14%bv : bv 5) = fcvt_s_w RNE (Z_to_bv 64 a) ->
  reg_get F (13%bv : bv 5) = fsub_s RNE (fcvt_s_w RNE (Z_to_bv 64 b)) (fcvt_s_w RNE (Z_to_bv 64 a)) ->
  reg_get F (12%bv : bv 5) = fcvt_s_w RNE (Z_to_bv 64 i) -> frm0 fc ->
  munch [(kfr, kfr + 1024)] m0 m -> wmono asegs m0 m ->
  u32arr asegs m kfr (map (Z_to_bv 64) kfs) -> length kfs = 256%nat -> Forall FpSiteB.kfr_le1 kfs ->
  wr_at asegs m kfr 1024 -> acc asegs m kfr 1024 -> mem_inv asegs m ->
  evt asegs (kfin_post kfr b S1 ra sp gp tp s0 s1 a3 a4 s2 (Z_to_bv 64 2147450880) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F0 m0)
    (MS (mkR ra sp gp tp (Z_to_bv 64 i) t1 t2 s0 s1 (Z_to_bv 64 kfr) (Z_to_bv 64 (kfr + 4 * i)) (Z_to_bv 64 (kfr + 4 * i)) a3 a4
             (Z_to_bv 64 1) (Z_to_bv 64 i) (Z_to_bv 64 1) s2 (Z_to_bv 64 2147450880) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xcff9c) fc None m (seg_rom asegs)).
Proof.
