Definition kfr_post (kfr maxval S1 : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F0 : bvmap 5 word) (m0 : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a1' a2' a4' a5' a6' a7' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem) (kfs' : list Z),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 (Z_to_bv 64 kfr) a1' a2' (Z_to_bv 64 maxval) a4' a5' a6' a7'
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F' (Z_to_bv 64 0xcf3a4) fc' None m' (seg_rom asegs)
    /\ fs_agree F0 F' /\ frm0 fc' /\ munch [(kfr, kfr + 1024)] m0 m' /\ wmono asegs m0 m' /\ mem_inv asegs m'
    /\ u32arr asegs m' kfr (map (Z_to_bv 64) kfs') /\ length kfs' = 256%nat /\ Forall FpSiteB.kfr_le1 kfs'
    /\ wr_at asegs m' kfr 1024 /\ acc asegs m' kfr 1024.
Lemma kfr_latch : forall (i k : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a1 a2 s2 s4 s6 s7 s8 s9 s10 s11 t4 t5 t6 : word)
    (F0 F : bvmap 5 word) (fc : bv 32) (m0 m : mem) (kfr maxval S1 : Z) (kfs : list Z),
  0 <= k <= 8 -> 0 <= i <= 255 -> 0 <= maxval <= 255 ->
  fs_agree F0 F -> frm0 fc -> munch [(kfr, kfr + 1024)] m0 m -> wmono asegs m0 m ->
  u32arr asegs m kfr (map (Z_to_bv 64) kfs) -> length kfs = 256%nat -> Forall FpSiteB.kfr_le1 kfs ->
  wr_at asegs m kfr 1024 -> acc asegs m kfr 1024 -> mem_inv asegs m ->
  (k + 1 < 9 -> i <= maxval ->
     evt asegs (kfr_post kfr maxval S1 ra sp gp tp s0 s1 s2 (Z_to_bv 64 2147450880) s4 (Z_to_bv 64 9) s6 s7 s8 s9 s10 s11
                          (Z_to_bv 64 11) t4 t5 t6 F0 m0)
       (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 kfr) a1 a2 (Z_to_bv 64 maxval) (Z_to_bv 64 (k + 1)) (Z_to_bv 64 1) (Z_to_bv 64 i) (Z_to_bv 64 1)
