Lemma kfr_outer : forall (j : nat) (i k : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a1 a2 s2 s4 s6 s7 s8 s9 s10 s11 t4 t5 t6 : word)
    (F0 F : bvmap 5 word) (fc : bv 32) (m0 m : mem) (kfr nc pmin pmax minval maxval S1 : Z) (ncs : list word) (kfs : list Z),
  Z.of_nat j = 9 - k -> 0 <= k <= 8 -> 0 <= i <= maxval ->
  (forall w, nth_error ncs (Z.to_nat k) = Some w -> bv_unsigned w <= i) ->
  0 < kfr -> kfr mod 16 = 0 -> kfr + 1024 <= 2^47 -> (kfr + 1024 <= 0x7fff7000 \/ 0x10007fff8000 <= kfr) ->
  0 < nc -> nc mod 16 = 0 -> nc + 40 <= 2^47 -> (nc + 40 <= 0x7fff7000 \/ 0x10007fff8000 <= nc) ->
  0 <= minval <= 255 -> 0 <= maxval <= 255 -> length ncs = 10%nat -> Forall (fun w => 0 <= bv_unsigned w <= 255) ncs ->
  0x10007fff8000 <= S1 -> S1 + 224 <= 2^47 -> (S1 + 224 <= kfr \/ kfr + 1024 <= S1) ->
  (forall m', munch [(kfr, kfr + 1024)] m0 m' -> wmono asegs m0 m' ->
       bc_karr_ro pmin pmax minval maxval nc ncs (S1 + 80) 11 m' /\ rw_cells asegs m' (S1 + 104) [C8 (Z_to_bv 64 nc)]
       /\ rw_cells asegs m' (S1 + 96) [C8 (Z_to_bv 64 (18446744073709551615 - nc))]) ->
  fs_agree F0 F -> frm0 fc -> munch [(kfr, kfr + 1024)] m0 m -> wmono asegs m0 m ->
  u32arr asegs m kfr (map (Z_to_bv 64) kfs) -> length kfs = 256%nat -> Forall FpSiteB.kfr_le1 kfs ->
  wr_at asegs m kfr 1024 -> acc asegs m kfr 1024 -> mem_inv asegs m ->
  s1 = Z_to_bv 64 S1 ->
  evt asegs (kfr_post kfr maxval S1 ra sp gp tp s0 s1 s2 (Z_to_bv 64 2147450880) s4 (Z_to_bv 64 9) s6 s7 s8 s9 s10 s11
                       (Z_to_bv 64 11) t4 t5 t6 F0 m0)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 kfr) a1 a2 (Z_to_bv 64 maxval) (Z_to_bv 64 k) (Z_to_bv 64 1) (Z_to_bv 64 i) (Z_to_bv 64 1)
             s2 (Z_to_bv 64 2147450880) s4 (Z_to_bv 64 9) s6 s7 s8 s9 s10 s11 (Z_to_bv 64 11) t4 t5 t6)
